SPUB_L = HEADCARD + IF('notPub', f'<div style="display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 40px; align-items: start"><div style="display: flex; flex-direction: column; gap: 16px">{_SPL}</div><div style="position: sticky; top: 0; display: flex; flex-direction: column; gap: 16px">{_SPR}</div></div>', 'true') + IF('isPub', _SPDONE)
_SHEAD = CARD(f'<div style="display: flex; align-items: center; gap: 16px"><span style="font-size: 28px; font-weight: 700; font-variant-numeric: tabular-nums">2×</span><span style="display: flex; flex-direction: column"><span style="font-size: 16px; font-weight: 600">Verse · bars 1–16</span><span style="font-size: 14px; color: {SOFT}">{{{{secChords}}}}</span></span></div>')
_SCH = SEC(S9CAPS('Chords', 'chords'), TIPCARD('chords', 'Learn each chord until your hands find it without looking: hold it, then play it in time.'), BOXG([f'<a href="Chords.dc.html" style="min-height: 56px; box-sizing: border-box; display: flex; align-items: center; gap: 12px; padding: 6px 16px; color: {INK}; text-decoration: none"><span style="flex: 1; font-size: 16px">Learn <b>{c}</b></span><span style="font-size: 14px; color: {k}; font-variant-numeric: tabular-nums">{v}</span><span style="color: {SOFT}; display: flex">{CHEV_R}</span></a>' for c, v, k in [('G', 'Done', GREEN)]][0] + IF('manyChords', ''.join(f'<a href="Chords.dc.html" style="min-height: 56px; box-sizing: border-box; display: flex; align-items: center; gap: 12px; padding: 6px 16px; color: {INK}; text-decoration: none; box-shadow: inset 0 1px 0 {FILL}"><span style="flex: 1; font-size: 16px">Learn <b>{c}</b></span><span style="font-size: 14px; color: {k}; font-variant-numeric: tabular-nums">{v}</span><span style="color: {SOFT}; display: flex">{CHEV_R}</span></a>' for c, v, k in [('C', 'Done', GREEN), ('D', '3 of 5', SOFT), ('Em', '0 of 5', SOFT)]), 'true')))
_STIME = SEC(S9CAPS('In time', 'time'), TIPCARD('time', 'The Player loops the chords at the song’s tempo with the click on. Play along in Wait mode to tick them off.'), GROUP(('link', 'Play the Verse at 80 BPM', '', 'Player.dc.html'), bg=SHEET))
_SCHG = IF('manyChords', SEC(S9CAPS('One change at a time', 'chg'), TIPCARD('chg', 'Each change on its own, back and forth, until it is smooth.'), BOXG(*[f'<a href="Player.dc.html" style="min-height: 56px; box-sizing: border-box; display: flex; align-items: center; gap: 12px; padding: 6px 16px; color: {INK}; text-decoration: none"><span style="flex: 1; font-size: 16px">{a} → {b}</span><span style="color: {SOFT}; display: flex">{CHEV_R}</span></a>' for a, b in [('G', 'C'), ('C', 'D'), ('D', 'Em')]]))
        , 'true')
_SPAT = SEC(S9CAPS('Patterns', 'pat'), TIPCARD('pat', 'The accompaniment the song uses, on each of its chords.'), GROUP(('link', 'Hymn, four-part · On G', '', 'Accompaniment.dc.html'), ('link', 'Hymn, four-part · On C', '', 'Accompaniment.dc.html'), bg=SHEET))
